    if (id === 'skills' || id === 'mcp' || id === 'websearch' || id === 'file-processing' || id === 'ocr')
        return 'capabilities';
    if (id === 'usage' || id === 'data' || id === 'appearance' || id === 'notifications')
        return 'personal';
